CREATE TABLE IF NOT EXISTS app_data (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS grammar_chapters (
        chapter_number INTEGER PRIMARY KEY,
        title_english TEXT,
        title_myanmar TEXT
      );
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(1,'Verbs (To work)','ကြိယာများ (အလုပ်လုပ်ခြင်းသရုပ်)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(2,'Pronouns','နာမ်စားများ (ပိုမိုစုံလင်သော လူပုဂ္ဂိုလ်နှင့် ဆွေမျိုးတော်စပ်မှုပြအသုံး)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(3,'Verbs','ကြိယာစနစ်များ (ပုံသေကြိယာ၊ ကြိယာထပ်မှုနှင့် အသွင်သရုပ်)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(4,'Adverbs','');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(5,'Adjectives','နာမဝိသေသနများ (Intransitive ကြိယာသရုပ်၊ နှိုင်းယှဉ်ချက်နှင့် နာမ်ပြုလုပ်ပုံ)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(6,'Articles & Determiners','သတ်မှတ်ချက်ပြ ပုဒ်များ (Articlesနှင့် ကိန်းပုံစံ လက္ခဏာရပ်များ)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(7,'Prepositions','ဝိဘတ်များ (နေရာနှင့် အချိန်ပိုင်း တည်နေရာညွှန်းဆိုပြစကားလုံးများ)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(8,'Coordinators','စကားဆက်များ (အစုဖွဲ့၊ ဆန့်ကျင်ဘက်နှင့် ရွေးချယ်မှုပြ ကောင်းမွန်သောအဆက်များ)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(9,'Word Order','ဝါကျအစီအစဉ် (ထိုင်းစကားပြော စကားလုံး စီစဉ်သတ်မှတ်ပုံစနစ်)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(10,'Tenses & Aspect','ကာလများနှင့် အသွင်သရုပ်ပြစနစ် (กำลัง - နေဆဲ / แล้ว - ပြီးပြီ)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(11,'Basic Sentences','အခြေခံ ဝါကျတည်ဆောက်ပုံများ (S-V-O နှင့် ပေါင်းစပ်ဝါကျတည်ဆောက်ပုံ)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(12,'The Passive Voice','ကံဟောဝါကျစနစ် (ဘေးဒုက္ခများအတွက် ''ถูก'' / ကောင်းသောကိစ္စအတွက် ''ได้รับ'')');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(13,'Forming Questions','မေးခွန်းဝါကျများ တည်ဆောက်ပုံ (ဟုတ်လား/မဟုတ်ဘူးလား နှင့် အချက်အလက်မေးမြန်းခြင်း)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(14,'Final Particles','ဝါကျအဆုံးသတ် စကားလုံးများ (ယဉ်ကျေးမှုထွက်စကားနှင့် ခံစားချက်ပြ particles)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(15,'Counting & Numbers','ဂဏန်းသင်္ချာ ရေတွက်ခြင်း (အခြေခံဂဏန်း၊ အစီအစဉ်ပြဂဏန်းနှင့် ရာဂဏန်းထက်ပိုပုံစံ)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(16,'Dates & Time','ရက်စွဲနှင့် အချိန် (ရက်သတ္တပတ်၊ လများနှင့် ထိုင်းစတုရဂံနာရီစနစ်)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(17,'Classifiers','လက္ခဏာစကားလုံးများ (အရာဝတ္ထုအမျိုးစုံတွဲဖက် ရေတွက်ပြစနစ်)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(18,'Interjections','အာမေဍိတ်များ (အံ့ဩခြင်း၊ အားပေးခြင်းနှင့် မကျေနပ်မှုများပြ ထိုင်းစကားလုံးများ)');
INSERT OR REPLACE INTO "grammar_chapters" ("chapter_number","title_english","title_myanmar") VALUES(19,'Idiomatic Expressions','စာအသုံးအနှုန်းနှင့် စကားအချိတ်အဆက် (နေ့စဉ်နှုတ်ဆက်နှင့် တုံ့ပြန်မှုစုဆောင်းချက်)');
