CREATE TABLE IF NOT EXISTS courses (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        description TEXT
      );
INSERT OR REPLACE INTO "courses" ("id","name","description") VALUES('course-basic','Complete Thai Foundational Mastery Course','Perfect for complete beginners. Cover Thai phonetic consonants, low/mid/high class letters, compound vowels, and tone rules with native audio worksheets and direct conversational practices.');
INSERT OR REPLACE INTO "courses" ("id","name","description") VALUES('course-business','Advanced Business Thai Speaking & Letters Course','Best for career professionals, translators, and cross-border business seekers. Master professional business email drafts, complex negotiation terms, formal speech patterns, and custom terminology.');
INSERT OR REPLACE INTO "courses" ("id","name","description") VALUES('course-workspace','Workspace & Professional Thai Learning Course','Master workplace communication, technical operations terminology, factory shift dialogues, and HR speech formulas for working in Thailand comfortably.');
INSERT OR REPLACE INTO "courses" ("id","name","description") VALUES('course-consonants-quick','Intensive Thai Consonants & Tones Quick-Crash Course','An intensive training track designed exclusively to master the 44 consonants, 32 vowels, and their complex tone combinations within days using active audio visual memory techniques.');
